        for(let i=3;i>=1;i--){ const q=Math.max(0,k-i*0.05), p=lerpP(st,end,q,0,Math.sin(q*Math.PI*3)*S*1.3); SG.puff(c,p.x,p.y+S*0.5,S*(0.5-i*0.1),0.25,[220,235,255]); }
