        if(o.trail) OWN.MT.trail(c,PF,f,t,f.s,o.trail,i);
        const age=t-f.t0, pop=f.sky?1:0.7+0.3*eo(Math.min(1,age/80)); if(!f.sky&&age<120) PF((f.a0||f.a).x,(f.a0||f.a).y,f.s*0.7*(1-age/120)+2,0.55*(1-age/120),[245,240,230]);
