      if(!o.keep&&k<0.3){ const q=k/0.3; c.save(); c.globalAlpha=1-q; c.translate(f.end.x,f.end.y+f.s*0.3*q); c.scale(1+0.35*q,1-0.4*q); OWN.MT.item(c,x,it,0,0,f.s,rotAt(i,f.t2),f.t2); c.restore(); }
