  const atk1=K.atk; K.atk=function(t,pos){ const b=atk1.call(this,t,pos), o=pos&&pos.name&&OWN_METEOR[pos.name], e=o&&o.atk&&o.atk(t,pos); return e?{...b,...e}:b; };
