      const sr=P.R*(0.85-0.35*eo(q)); runes(fx,fy,sr*1.25,(1-q)*al,-t/250); OWN.CH.sigil(c,fx,fy,sr,yel,al*(0.75+0.25*Math.sin(t/45)),t);
