      const end=B.lp(ctr,P.tg,t<200?0:B.L(t)), dx=fx-ctr.x, dy=fy-ctr.y, Ln=Math.hypot(dx,dy)||1, nx=-dy/Ln, ny=dx/Ln, gl=[];
