        c.fillStyle="rgba(255,250,235,.9)"; c.beginPath(); c.ellipse(-w*0.1,-h+w*0.1,w*0.32,w*0.16,0,0,7); c.fill(); c.strokeStyle="#4a3a30"; c.lineWidth=Math.max(1,s*0.05); c.beginPath(); c.moveTo(0,-h); c.lineTo(0,-h-s*0.12); c.stroke();
