        const N=34, s=P.S, pt=u=>({x:(1-u)*(1-u)*B.x+2*u*(1-u)*C.x+u*u*T.x,y:(1-u)*(1-u)*B.y+2*u*(1-u)*C.y+u*u*T.y}), tg=u=>{ const dx=2*(1-u)*(C.x-B.x)+2*u*(T.x-C.x), dy=2*(1-u)*(C.y-B.y)+2*u*(T.y-C.y), m=Math.hypot(dx,dy)||1; return {x:dx/m,y:dy/m}; };
