        for(const sd of [-1,1]){ const r=eo(L.up(t,420,560)); c.save(); c.globalAlpha=a; c.fillStyle="#efe6d0"; c.beginPath(); c.ellipse(P.tg.x+sd*P.R*0.5,g-P.S*0.3*r,P.S*0.3,P.S*0.55*r,sd*0.3,0,7); c.fill(); c.strokeStyle="rgba(150,130,100,.6)"; c.lineWidth=1.2; for(let j=0;j<3;j++){ c.beginPath(); c.moveTo(P.tg.x+sd*P.R*0.5-P.S*0.25,g-P.S*(0.1+0.25*j)*r); c.lineTo(P.tg.x+sd*P.R*0.5+P.S*0.25,g-P.S*(0.2+0.25*j)*r); c.stroke(); } c.restore(); }
